function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 200) return 'nums needs 1 to 200 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value in nums is an integer from 1 to 100.';
  if (!Number.isInteger(k) || k < 1 || k > 99) return 'k is an integer from 1 to 99.';
  return null;
}

