function countKDifference(nums, k) {
  const seen = new Map();
  let pairs = 0;

  for (const num of nums) {
    pairs += seen.get(num - k) ?? 0;
    pairs += seen.get(num + k) ?? 0;
    seen.set(num, (seen.get(num) ?? 0) + 1);
  }
  return pairs;
}

