function generate(rand, size) {
  const n = size === 'large' ? 200 : 1 + Math.floor(rand() * 10);
  const span = size === 'large' ? (rand() < 0.5 ? 100 : 20) : 1 + Math.floor(rand() * 8);
  const low = 1 + Math.floor(rand() * (101 - span));
  const nums = Array.from({ length: n }, () => low + Math.floor(rand() * span));
  const k = 1 + Math.floor(rand() * Math.min(99, span + 1));
  return [nums, k];
}
